INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 33, 'theory', 'Quiz: tokio — runtime and spawn');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 0, 'What does tokio::spawn return?', '["the result of the future immediately", "JoinHandle<T>", "a Future that is not started", "an OS thread"]', 1, 'The task starts right away; .await on the handle gives Result<T, JoinError>.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 1, 'What happens to a task if it panics?', '["the panic is isolated: the handle returns a JoinError with is_panic()", "the whole runtime goes down", "the program exits", "the panic is silently ignored"]', 0, 'The runtime keeps running; the error reaches whoever is waiting for the result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 2, 'Where should you send a blocking call so it does not occupy a worker thread?', '["to tokio::spawn", "to join!", "to yield_now", "to spawn_blocking"]', 3, 'A closure passed to spawn_blocking runs in a separate thread pool.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 3, 'What happens to unfinished tasks when main returns?', '["the runtime waits for them", "they continue in the background", "they are cancelled: the runtime is destroyed", "the program hangs"]', 2, 'Wait for important tasks explicitly via JoinHandle or JoinSet.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 4, 'What are LocalSet and spawn_local for?', '["running Send tasks faster", "tasks that are not Send, on a single thread", "blocking code", "timers"]', 1, 'They solve the "future is not Send" error when the task must not change threads.');
